#!/usr/bin/env python3
"""CPU measurements of Hydra: input C++ code (scalar, OpenMP) and ISPC code generated by kernel_slicer
(wavefront and megakernel), RTAO and MIS-PT, like Table 5 of the paper.

Standard library only.

  python3 testing/run_ispc_bench.py run    --out profiling_results/ispc/bench
  python3 testing/run_ispc_bench.py report --out profiling_results/ispc/bench --tex profiling/reports/ispc-mega-wave.tex

Binaries: bin-release/hydra_cpu (CMake option HYDRA_EXE_NAME=hydra_cpu), bin-release/hydra_ispc_wave and
bin-release/hydra_ispc_mega (ispc_build.sh). References: profiling_results/ispc/references (make_references.sh).
"""

import argparse
import json
import math
import os
from pathlib import Path
import platform
import re
import statistics
import struct
import subprocess
from datetime import datetime, timezone

ROOT = Path(__file__).resolve().parents[1]
SCENES = ["coffee", "spaceship", "staircase", "kitchen"]
SCENE_NAMES = {"coffee": "Coffee", "spaceship": "Spaceship", "staircase": "Staircase", "kitchen": "Kitchen"}
INTEGRATORS = {"rtao": "AmbientOcclusionBlock", "mispt": "PathTraceBlock"}
VARIANTS = {
    "cpu":       ("bin-release/hydra_cpu",       []),
    "ispc-wave": ("bin-release/hydra_ispc_wave", ["--ispc"]),
    "ispc-mega": ("bin-release/hydra_ispc_mega", ["--ispc"]),
}


def read_bmp(path):
    """(width, height, bytes BGR rows) of uncompressed 24 or 32 bit BMP"""
    data = Path(path).read_bytes()
    if data[:2] != b"BM":
        raise ValueError(f"not a BMP: {path}")
    offset = struct.unpack_from("<I", data, 10)[0]
    width, height = struct.unpack_from("<ii", data, 18)
    bpp = struct.unpack_from("<H", data, 28)[0]
    if bpp not in (24, 32):
        raise ValueError(f"unsupported BMP: {path}")
    stride = (width * (bpp // 8) + 3) & ~3
    pixels = bytearray()
    for row in range(abs(height)):
        line = data[offset + row * stride: offset + row * stride + width * (bpp // 8)]
        if bpp == 32:
            line = bytes(b for i, b in enumerate(line) if i % 4 != 3)
        pixels += line
    return width, abs(height), bytes(pixels)


def psnr(path_a, path_b):
    wa, ha, a = read_bmp(path_a)
    wb, hb, b = read_bmp(path_b)
    if (wa, ha) != (wb, hb):
        raise ValueError(f"different sizes: {path_a}, {path_b}")
    mse = sum((x - y) * (x - y) for x, y in zip(a, b)) / len(a)
    return 99.0 if mse == 0 else 10.0 * math.log10(255.0 * 255.0 / mse)


def machine_info():
    cpu = platform.processor()
    try:
        for line in Path("/proc/cpuinfo").read_text().splitlines():
            if line.startswith("model name"):
                cpu = line.split(":", 1)[1].strip()
                break
    except OSError:
        pass
    ispc = subprocess.run(["ispc", "--version"], capture_output=True, text=True).stdout.strip()
    return {"cpu": cpu, "logical_cpus": os.cpu_count(), "ispc": ispc, "system": platform.platform(),
            "omp_num_threads": os.environ.get("OMP_NUM_THREADS", "")}


def run(args):
    out = args.out.resolve()
    out.mkdir(parents=True, exist_ok=True)
    results_path = out / "results.json"
    results = json.loads(results_path.read_text()) if results_path.exists() else {"records": []}
    results["machine"] = machine_info()
    results["settings"] = {"width": args.width, "height": args.height, "spp": args.spp, "runs": args.runs}
    done = {(r["scene"], r["integrator"], r["variant"]) for r in results["records"]}
    for scene in args.scenes:
        for integrator in args.integrators:
            for variant in args.variants:
                if (scene, integrator, variant) in done and not args.rerun:
                    continue
                binary, flags = VARIANTS[variant]
                image = out / f"{scene}_{integrator}_{variant}.bmp"
                times = []
                for i in range(args.runs):
                    command = [str(ROOT / binary)] + flags + [
                        "-in", str(ROOT / "scenes/benchmark" / scene / "statex_00001.xml"), "-integrator", integrator,
                        "-width", str(args.width), "-height", str(args.height), "-spp", str(args.spp), "-out", str(image)]
                    print("Running:", " ".join(command), flush=True)
                    log = subprocess.run(command, cwd=ROOT, capture_output=True, text=True)
                    (out / f"{scene}_{integrator}_{variant}_{i}.log").write_text(log.stdout + log.stderr)
                    if log.returncode != 0:
                        raise RuntimeError(f"exit code {log.returncode}, see {scene}_{integrator}_{variant}_{i}.log")
                    match = re.search(INTEGRATORS[integrator] + r"\(exec\)\s*=\s*([0-9.]+)\s*ms", log.stdout)
                    if match is None:
                        raise RuntimeError(f"no time in {scene}_{integrator}_{variant}_{i}.log")
                    times.append(float(match.group(1)))
                reference = ROOT / "profiling_results/ispc/references" / f"{scene}_{integrator}.bmp"
                record = {"scene": scene, "integrator": integrator, "variant": variant, "times_ms": times,
                          "median_ms": statistics.median(times),
                          "psnr": psnr(reference, image) if reference.exists() else None,
                          "date": datetime.now(timezone.utc).isoformat()}
                results["records"] = [r for r in results["records"] if (r["scene"], r["integrator"], r["variant"]) != (scene, integrator, variant)]
                results["records"].append(record)
                results_path.write_text(json.dumps(results, indent=2) + "\n")
                print(f"  {scene} {integrator} {variant}: {record['median_ms']:.1f} ms, PSNR {record['psnr']}", flush=True)


def fmt_time(ms):
    """the same style as Table 5: '93.6 ms', '213 ms', '2.28 s', '10.8 s'"""
    if ms < 100.0:
        return f"{ms:.1f} ms"
    if ms < 1000.0:
        return f"{ms:.0f} ms"
    s = ms / 1000.0
    if s < 10.0:
        return f"{s:.2f} s"
    if s < 100.0:
        return f"{s:.1f} s"
    return f"{s:.0f} s"


def report(args):
    results = json.loads((args.out.resolve() / "results.json").read_text())
    settings, machine = results["settings"], results["machine"]
    scale = args.target_spp / settings["spp"]
    table = {(r["scene"], r["integrator"], r["variant"]): r for r in results["records"]}
    order = ["cpu", "ispc-wave", "ispc-mega"]
    lines = []
    lines.append("% generated by HydraCore3/testing/run_ispc_bench.py report; do not edit by hand")
    lines.append("\\begin{table*}[h]")
    lines.append("\t\\centering")
    lines.append("\t\\caption{\\label{tab:rtao-mega-cpu} CPU rendering time of the same scenes as in Table 5 of the paper, "
                 f"{settings['width']}x{settings['height']}, {args.target_spp} samples per pixel "
                 f"(measured with {settings['spp']} spp and multiplied by {scale:g}). "
                 "``scalar'' -- input C++ code of the renderer (OpenMP, Embree with single rays); "
                 "``wave'' and ``mega'' -- ISPC code generated by our translator from the same input code "
                 "with wavefront and megakernel execution strategies (OpenMP over chunks of threads, "
                 f"Embree with packets of rays, target \\texttt{{avx2-i32x8}}). CPU: {machine['cpu']}. "
                 "Best result in row is marked with bold text within each part of the table.}")
    lines.append("\t\\begin{tabular}{|c|c|c|c|c|c|c|}")
    lines.append("\t\t\\hline")
    lines.append("\t\t & \\multicolumn{3}{c|}{Ambient Occlusion} & \\multicolumn{3}{c|}{Path Tracing} \\\\")
    lines.append("\t\t\\hline")
    lines.append("\t\tscene & scalar & wave & mega & scalar & wave & mega \\\\")
    lines.append("\t\t\\hline")
    for scene in SCENES:
        cells = []
        for integrator in ["rtao", "mispt"]:
            values = [table.get((scene, integrator, v)) for v in order]
            times = [r["median_ms"] * scale if r else None for r in values]
            best = min((t for t in times if t is not None), default=None)
            for t in times:
                if t is None:
                    cells.append("--")
                else:
                    text = fmt_time(t)
                    cells.append(f"\\textbf{{{text}}}" if t == best else text)
        lines.append(f"\t\t{SCENE_NAMES[scene]} & " + " & ".join(cells) + " \\\\")
        lines.append("\t\t\\hline")
    lines.append("\t\\end{tabular}")
    lines.append("\\end{table*}")
    lines.append("")
    # PSNR against GPU references and against GPU images with the same number of samples
    out = args.out.resolve()
    references = ROOT / "profiling_results/ispc/references"
    lines.append("\\begin{table*}[h]")
    lines.append("\t\\centering")
    lines.append("\t\\caption{\\label{tab:rtao-mega-cpu-psnr} PSNR (dB) of CPU images of table~\\ref{tab:rtao-mega-cpu} "
                 f"({settings['spp']} spp). ``ref'' -- against references rendered on GPU by the generated Vulkan code "
                 "(path tracing: 4096 spp, ambient occlusion: 1024 spp), it is limited by Monte Carlo noise; "
                 f"``GPU'' -- against GPU images with the same {settings['spp']} spp and the same random numbers. "
                 "Wavefront and megakernel ISPC images are equal.}")
    lines.append("\t\\begin{tabular}{|c|c|c|c|c|c|c|}")
    lines.append("\t\t\\hline")
    lines.append("\t\t & \\multicolumn{3}{c|}{AO} & \\multicolumn{3}{c|}{PT} \\\\")
    lines.append("\t\t\\hline")
    lines.append("\t\tscene & scalar, ref & ISPC, ref & ISPC, GPU & scalar, ref & ISPC, ref & ISPC, GPU \\\\")
    lines.append("\t\t\\hline")
    for scene in SCENES:
        cells = []
        for integrator in ["rtao", "mispt"]:
            for v in ["cpu", "ispc-mega"]:
                r = table.get((scene, integrator, v))
                cells.append(f"{r['psnr']:.1f}" if r and r["psnr"] is not None else "--")
            same = references / f"{scene}_{integrator}_64spp.bmp"
            image = out / f"{scene}_{integrator}_ispc-mega.bmp"
            cells.append(f"{psnr(same, image):.1f}" if same.exists() and image.exists() else "--")
        lines.append(f"\t\t{SCENE_NAMES[scene]} & " + " & ".join(cells) + " \\\\")
        lines.append("\t\t\\hline")
    lines.append("\t\\end{tabular}")
    lines.append("\\end{table*}")
    text = "\n".join(lines) + "\n"
    if args.tex:
        Path(args.tex).write_text(text)
        print(f"written {args.tex}")
    else:
        print(text)


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = parser.add_subparsers(dest="command", required=True)
    r = sub.add_parser("run", help="render scenes and write results.json")
    r.add_argument("--out", type=Path, default=ROOT / "profiling_results/ispc/bench")
    r.add_argument("--scenes", nargs="+", choices=SCENES, default=SCENES)
    r.add_argument("--integrators", nargs="+", choices=list(INTEGRATORS), default=list(INTEGRATORS))
    r.add_argument("--variants", nargs="+", choices=list(VARIANTS), default=list(VARIANTS))
    r.add_argument("--width", type=int, default=1024)
    r.add_argument("--height", type=int, default=1024)
    r.add_argument("--spp", type=int, default=64)
    r.add_argument("--runs", type=int, default=3)
    r.add_argument("--rerun", action="store_true", help="measure again records which are already in results.json")
    t = sub.add_parser("report", help="LaTeX tables from results.json")
    t.add_argument("--out", type=Path, default=ROOT / "profiling_results/ispc/bench")
    t.add_argument("--target-spp", type=int, default=256, help="times are scaled to this number of samples per pixel")
    t.add_argument("--tex", help="output .tex file (stdout by default)")
    args = parser.parse_args()
    run(args) if args.command == "run" else report(args)


if __name__ == "__main__":
    main()
